{
  "findings": [
    {
      "ref": "[D537]",
      "area": "contact",
      "claim": "A parent reports that strangers can send friend requests to children on Roblox.",
      "stance": "risk",
      "quote": "some children have reported unsolicited friend requests from strangers."
    },
    {
      "ref": "[D537]",
      "area": "contact",
      "claim": "Voice chat is enabled by default and can be turned off via privacy settings.",
      "stance": "mitigation",
      "quote": "Select ‘No one’ under the “Who can chat with me?” option"
    },
    {
      "ref": "[D537]",
      "area": "money",
      "claim": "The app encourages in‑game currency purchases that can be used to exploit children.",
      "stance": "risk",
      "quote": "the temptation or requirement to buy in–game currency to improve gameplay can also be used to exploit children."
    },
    {
      "ref": "[D537]",
      "area": "data",
      "claim": "Roblox collects personal data for advertising and may share it with third parties, and the data can be deleted.",
