      "quote": "The platform's Terms of Use say that users under the age of 18 require parental consent to use the services."
    },
    {
      "ref": "[D537]",
      "area": "age_gating",
      "claim": "Age verification is optional and relies on an ID document check and selfie match.",
      "stance": "mitigation",
      "quote": "Players must go through this verification process to engage in certain features like Spatial (3D) Voice. This involves an ID document check and selfie match."
    },
    {
      "ref": "[D537]",
      "area": "content",
      "claim": "A parent reports exposure to sexualised content and simulated sex acts in the game Brookhaven.",
